window.TERREN_DATA={"copy":{"pl":{"navHome":"START","navProjects":"PROJEKTY","navOffer":"OFERTA","navStudio":"STUDIO","navContact":"KONTAKT","navJournal":"INSPIRACJE","menu":"Menu","close":"Zamknij menu","back":"POWRÓT NA GÓRĘ ↑","concept":"KONCEPCJA","projectsTitle":"WYBRANE PROJEKTY","projectsIntro":"Różne miejsca, jedna wrażliwość. Poznaj nasze koncepcje ogrodów — od kameralnych dziedzińców po otwarte krajobrazy.","all":"WSZYSTKIE","natural":"NATURALISTYCZNE","private":"PRYWATNE","courtyard":"DZIEDZIŃCE","demo":"Robocze portfolio koncepcyjne. Listę realizacji uzupełnimy w kolejnym etapie.","offerTitle":"OFERTA","offerIntro":"Od pierwszej rozmowy po dopracowany ogród. Wybierz zakres, który odpowiada potrzebom Twojego miejsca.","studioTitle":"O STUDIU","studioIntro":"Pracownia architektury krajobrazu. Warszawa, od 2016 roku.","studioBody":"TERREN powstało z potrzeby tworzenia miejsc, w których architektura i natura pozostają w równowadze. Zaczynamy od rozmowy, codziennych rytuałów i tego, co już istnieje. Szukamy klarownych proporcji, naturalnych faktur i zieleni, która z czasem zyskuje głębię.","studioBody2":"Projekt traktujemy jako całość: ogród, dom, światło i sposób życia. Lubimy proste decyzje, za którymi stoi uważna obserwacja. Dzięki nim miejsce jest osobiste, wygodne i spokojne.","studioNote":"WIZJA PRACOWNI / TERREN","contactTitle":"KONTAKT","contactIntro":"Opowiedz nam o swoim miejscu. Od tego zaczyna się dobra współpraca.","journalTitle":"INSPIRACJE","journalIntro":"Kilka spojrzeń na krajobraz, architekturę i codzienność w ogrodzie.","read":"CZYTAJ DALEJ ↗","talk":"POROZMAWIAJMY ↗","ctaTitle":"TWOJE MIEJSCE. NOWA PERSPEKTYWA.","ctaText":"Zacznij od kilku słów o ogrodzie, który chcesz stworzyć.","projectAbout":"O KONCEPCJI","projectOther":"KOLEJNY OGRÓD","projectBack":"WSZYSTKIE PROJEKTY ↗","articleBack":"WSZYSTKIE INSPIRACJE ↗","scope":"ZAKRES","formName":"Imię i nazwisko","formEmail":"Adres e-mail","formPhone":"Telefon — opcjonalnie","place":"Miejscowość","formMessage":"Opowiedz o swoim ogrodzie","formSend":"WYŚLIJ ZAPYTANIE","formDemo":"Formularz demonstracyjny. Dane nie są wysyłane.","contactHeading":"ZACZNIJMY OD ROZMOWY","contactCopy":"Kilka słów o Tobie i miejscu, które chcesz zmienić."},"en":{"navHome":"HOME","navProjects":"PROJECTS","navOffer":"SERVICES","navStudio":"STUDIO","navContact":"CONTACT","navJournal":"JOURNAL","menu":"Menu","close":"Close menu","back":"BACK TO TOP ↑","concept":"CONCEPT","projectsTitle":"SELECTED PROJECTS","projectsIntro":"Different places, one sensibility. Explore our garden concepts — from intimate courtyards to open landscapes.","all":"ALL","natural":"NATURALISTIC","private":"PRIVATE","courtyard":"COURTYARDS","demo":"Working concept portfolio. The project list will be completed in the next stage.","offerTitle":"SERVICES","offerIntro":"From the first conversation to a considered garden. Choose the scope that fits the needs of your place.","studioTitle":"THE STUDIO","studioIntro":"A landscape architecture studio. Warsaw, since 2016.","studioBody":"TERREN grew from a desire to create places where architecture and nature remain in balance. We begin with conversation, everyday rituals, and what already exists. We seek clear proportions, natural textures, and planting that grows richer with time.","studioBody2":"We consider the project as a whole: garden, home, light, and way of life. We value simple decisions informed by careful observation. They make a place personal, comfortable, and calm.","studioNote":"A STUDIO VISION / TERREN","contactTitle":"CONTACT","contactIntro":"Tell us about your place. That is where good collaboration begins.","journalTitle":"JOURNAL","journalIntro":"A few perspectives on landscape, architecture, and everyday life in a garden.","read":"READ MORE ↗","talk":"LET’S TALK ↗","ctaTitle":"YOUR PLACE. A NEW PERSPECTIVE.","ctaText":"Start with a few words about the garden you want to create.","projectAbout":"ABOUT THE CONCEPT","projectOther":"NEXT GARDEN","projectBack":"ALL PROJECTS ↗","articleBack":"ALL JOURNAL ENTRIES ↗","scope":"SCOPE","formName":"Full name","formEmail":"Email address","formPhone":"Phone — optional","place":"Location","formMessage":"Tell us about your garden","formSend":"SEND ENQUIRY","formDemo":"Demonstration form. No information is sent.","contactHeading":"LET’S START A CONVERSATION","contactCopy":"A few words about you and the place you want to transform."}},"projects":[{"city":["WARSZAWA","WARSAW"],"type":"private","image":"italian-garden.jpg","desc":["Włoska geometria, oliwki i naturalny kamień.","Italian geometry, olive trees, and natural stone."],"text":["Koncepcja oparta na spokojnej geometrii. Żwirowa oś porządkuje przestrzeń, a rytm cyprysów i strzyżonej zieleni buduje jej architektoniczny charakter. Naturalny kamień i miękkie światło łączą ogród z domem.","A concept built on quiet geometry. A gravel axis organises the space, while cypresses and clipped greenery give it architectural character. Natural stone and soft light connect garden and home."]},{"city":["WROCŁAW","WROCŁAW"],"type":"natural","image":"meadow.jpg","desc":["Swobodny krajobraz na skraju lasu.","An open landscape at the forest’s edge."],"text":["Swobodna kompozycja traw i bylin pozwala ogrodowi przenikać się z otoczeniem. Miękka ścieżka prowadzi przez kolejne warstwy zieleni. Głównym tematem jest zmienność — faktur, światła i sezonów.","A loose composition of grasses and perennials allows the garden to blend with its surroundings. A soft path leads through layers of greenery. Change is the central theme: texture, light, and seasons."]},{"city":["KRAKÓW","KRAKÓW"],"type":"courtyard","image":"courtyard.jpg","desc":["Drzewo, kamień i kameralna przestrzeń.","A tree, stone, and an intimate space."],"text":["Kameralny dziedziniec zamknięty w prostych ramach architektury. Jedno drzewo, jasny kamień i warstwy zieleni tworzą miejsce do odpoczynku. Mniej elementów daje więcej przestrzeni na codzienność.","An intimate courtyard framed by simple architecture. One tree, pale stone, and layers of greenery create a place to rest. Fewer elements leave more room for everyday life."]},{"city":["POZNAŃ","POZNAŃ"],"type":"private","image":"reflecting-garden.jpg","desc":["Ogród wokół spokojnej tafli wody.","A garden around quiet water."],"text":["Lustro wody porządkuje perspektywę i wprowadza spokój. Oliwki, cyprysy i naturalne faktury tworzą warstwy krajobrazu. Projekt jest studium odbić, proporcji i światła.","A reflecting pool organises the perspective and brings calm. Olive trees, cypresses, and natural textures create layers of landscape. The project is a study in reflections, proportions, and light."]},{"city":["GDAŃSK","GDAŃSK"],"type":"natural","image":"hero.jpg","desc":["Miękkie trawy i jasny kamienny pawilon.","Soft grasses and a pale stone pavilion."],"text":["Przestrzeń pomiędzy domem a naturalnym krajobrazem. Kamienna ścieżka i niewielki pawilon wpisują się w swobodny rytm roślin. Ogród zachęca do wolniejszego tempa i spokojnej obecności.","A space between home and natural landscape. A stone path and small pavilion belong to the loose rhythm of planting. The garden invites a slower pace and quiet presence."]}],"services":[{"title":["KONCEPCJA OGRODU","GARDEN CONCEPT"],"text":["Pierwszy spójny obraz miejsca. Porządkujemy potrzeby i budujemy kierunek całego projektu.","A coherent first vision. We organise needs and establish the direction of the whole project."],"items":[["Układ przestrzeni","Kierunek materiałów","Atmosfera i nasadzenia"],["Spatial layout","Material direction","Atmosphere and planting"]],"image":"italian-garden.jpg"},{"title":["PROJEKT KOMPLEKSOWY","COMPLETE DESIGN"],"text":["Przekładamy koncepcję na rozwiązania do realizacji. Każda część ogrodu staje się elementem jednej opowieści.","We turn a concept into considered solutions for implementation. Every part of the garden belongs to one story."],"items":[["Ścieżki i tarasy","Detale przestrzeni","Dokumentacja projektowa"],["Paths and terraces","Spatial details","Design documentation"]],"image":"studio.jpg"},{"title":["ROŚLINY I MATERIAŁY","PLANTS & MATERIALS"],"text":["Dobieramy zieleń oraz naturalne faktury z myślą o miejscu, świetle i zmianach w czasie.","We select planting and natural textures with the place, light, and change over time in mind."],"items":[["Kompozycja nasadzeń","Paleta materiałów","Sezonowość ogrodu"],["Planting composition","Material palette","Garden seasonality"]],"image":"meadow.jpg"},{"title":["WSPARCIE REALIZACJI","PROJECT SUPPORT"],"text":["Towarzyszymy kolejnym decyzjom wykonawczym, aby zachować spójność projektu i jego detali.","We support implementation decisions to preserve the coherence of the design and its details."],"items":[["Konsultacje","Dobór rozwiązań","Uważność na detal"],["Consultation","Solution choices","Attention to detail"]],"image":"courtyard.jpg"}],"articles":[{"title":["OGRÓD JAKO PRZEDŁUŻENIE DOMU","THE GARDEN AS AN EXTENSION OF HOME"],"image":"hero.jpg","intro":["Dobra przestrzeń nie kończy się na progu.","A good space does not end at the doorstep."],"body":[["Myślenie o domu i ogrodzie jako o jednej całości zaczyna się od prostych pytań: gdzie pada światło, dokąd prowadzi widok i w którym miejscu najchętniej zatrzymujemy się na chwilę.","Taras, ścieżka i nasadzenia nie muszą konkurować z architekturą. Mogą ją uzupełniać, prowadząc codzienność na zewnątrz. Spójna paleta materiałów i czytelne proporcje pomagają zbudować tę relację."],["Thinking of home and garden as one place begins with simple questions: where does the light fall, where does the view lead, and where do we naturally pause?","A terrace, a path, and planting do not need to compete with architecture. They can complement it, bringing everyday life outdoors. A coherent material palette and clear proportions help build that relationship."]]},{"title":["PIĘKNO NATURALNYCH FAKTUR","THE BEAUTY OF NATURAL TEXTURES"],"image":"studio.jpg","intro":["Kamień, drewno i ślady czasu.","Stone, wood, and traces of time."],"body":[["Naturalne materiały wprowadzają do ogrodu spokojną różnorodność. Ich faktury zmieniają się wraz ze światłem i pogodą, a patyna dodaje miejscu charakteru.","Zamiast wielu efektów szukamy kilku dobrze dobranych elementów. Ciepły kamień, drewno i zieleń mogą stworzyć prostą, ale bogatą opowieść."],["Natural materials bring quiet variety to a garden. Their textures change with light and weather, while patina adds character to the place.","Rather than many effects, we look for a few well-chosen elements. Warm stone, wood, and greenery can create a simple yet rich story."]]},{"title":["CZTERY PORY JEDNEGO OGRODU","FOUR SEASONS OF ONE GARDEN"],"image":"meadow.jpg","intro":["Krajobraz, który pozostaje w ruchu.","A landscape that stays in motion."],"body":[["Ogród nie jest jednym skończonym obrazem. To zbiór zmieniających się scen — nowych liści, letnich kwiatów, jesiennych faktur i zimowej struktury.","Projektując, myślimy o tym rytmie. Pozwalamy, aby kolejne pory roku odsłaniały inne proporcje i inne światło, zachowując charakter miejsca."],["A garden is not one finished image. It is a collection of changing scenes: new leaves, summer flowers, autumn textures, and winter structure.","We design with this rhythm in mind, allowing each season to reveal different proportions and light while preserving the character of the place."]]}]};
